-- turn_session_minutes(uuid,uuid)
CREATE OR REPLACE FUNCTION public.turn_session_minutes(p_actor_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s runtime_sessions;
BEGIN
  -- CONTENT-CONVERSATION-2 (0542): the minutes of one conversation, newest first, by the owner's key only; nothing is written.
  -- As turn_session_view: a disabled account and a deleted conversation read nothing.
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_actor_id AND status = 'active' AND is_deleted::text = 'false') THEN
    RAISE EXCEPTION 'TURN_ACCOUNT_DENIED' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM runtime_sessions WHERE id = p_session_id AND actor_id = p_actor_id;
  IF s.id IS NULL THEN RAISE EXCEPTION 'TURN_SESSION_DENIED' USING ERRCODE='42501'; END IF;
  IF s.content_deleted_at IS NOT NULL OR s.erased_at IS NOT NULL THEN RAISE EXCEPTION 'TURN_SESSION_ERASED' USING ERRCODE='42501'; END IF;
  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('turnId', t.id, 'requestId', t.request_id, 'state', t.state,
      'closeKind', t.close_kind, 'failureCode', t.failure_code, 'chargedCredits', t.charged_credits,
      'openedAt', t.opened_at, 'closedAt', t.closed_at,
      -- A deleted message keeps its row with empty content: the minutes are shown as no longer available.
      'body', nullif(m.content, ''), 'available', m.seq IS NOT NULL AND m.deleted_at IS NULL AND m.content <> '')
    ORDER BY t.opened_at DESC, t.id DESC)
    FROM turns t LEFT JOIN session_messages m ON m.session_id = p_session_id AND m.turn_id = t.id AND m.role = 'assistant'
    WHERE t.actor_id = p_actor_id AND t.session_id = p_session_id AND t.kind = 'minutes'), '[]'::jsonb);
END $function$;
